dashboard.definition:
{
  "title": "Support overview",
  "description": "When did it start, who is affected, and what is the likely cause?",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {"token": "time", "defaultValue": "-4h,now"}
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {"queryParameters": {"earliest": "$time.earliest$", "latest": "$time.latest$"}}
      }
    }
  },
  "dataSources": {
    "ds_failures": {
      "type": "ds.search",
      "name": "Failures with their likely cause",
      "options": {"query": "(`support_failures`) OR (`support_index` sourcetype=idlab:slapd ldap_op=BIND bind_dn=*) OR (`support_radius_mfa_events`) OR (`support_kc_user_ids`) OR (`support_index` eventtype=idlab_keycloak_admin_event signature=kc_admin_realm_update) | append [search `support_redirect_loops`] | `support_radius_mfa` | `support_kc_user_from_id` | where isnull(kcid_join_only) | eventstats values(bind_dn) as bind_dn by host conn op | where isnull(ldap_op) OR ldap_op!=\"BIND\" | eval bind_dn=mvindex(bind_dn, 0), bind_uid=if(match(bind_dn, \"^uid=\"), replace(bind_dn, \"^uid=([^,]+),.*$\", \"\\1\"), null()), bind_cn=if(match(bind_dn, \"^cn=\"), replace(bind_dn, \"^cn=([^,]+),.*$\", \"\\1\"), null()), user=coalesce(user, bind_uid), signature=if(signature==\"ldap_bind_49\" AND isnotnull(bind_uid), \"ldap_user_bind_49\", signature) | lookup support_causes signature OUTPUT cause runbook runbook_url | eval cause=coalesce(cause, \"unknown: \" . signature), who=case(isnotnull(user), user, isnotnull(bind_cn), \"service account (\" . bind_cn . \")\", isnotnull(client_dn), \"client certificate (\" . client_dn . \")\", like(signature, \"ldap_bind_%\"), null(), true(), \"not in log\") | `support_count_once_per_login` | eval counted=if(rmfa_uncounted==1, 0, counted), is_change=if(signature==\"kc_admin_realm_update\", 1, null()) | fields _time user who app route cause signature runbook runbook_url counted token_lifetime is_change user_from_id nas_client"}
    },
    "ds_totals": {
      "type": "ds.chain",
      "name": "Totals",
      "options": {"extend": "ds_failures", "query": "| where isnull(is_change) | stats sum(counted) as count dc(user) as users min(_time) as first max(_time) as last"}
    },
    "ds_count": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| fields count"}},
    "ds_users": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| fields users"}},
    "ds_first": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| eval first=strftime(first, \"%Y-%m-%d %H:%M:%S\") | fields first"}},
    "ds_last": {"type": "ds.chain", "options": {"extend": "ds_totals", "query": "| eval last=strftime(last, \"%Y-%m-%d %H:%M:%S\") | fields last"}},
    "ds_over_time": {
      "type": "ds.chain",
      "name": "Failures over time by cause",
      "options": {"extend": "ds_failures", "query": "| where counted=1 AND isnull(is_change) | `support_chart(cause)`"}
    },
    "ds_by_cause": {
      "type": "ds.chain",
      "name": "When did it start, by cause",
      "options": {"extend": "ds_failures", "query": "| stats min(_time) as first_seen max(_time) as last_seen sum(counted) as count dc(user) as n_users values(who) as who values(signature) as signatures values(app) as apps values(route) as routes min(token_lifetime) as token_lifetime latest(runbook) as runbook latest(runbook_url) as runbook_url by cause | eval cause=if(isnotnull(mvfind(signatures, \"^api_bearer_expired$\")), cause . case(isnull(token_lifetime), \". Token lifetime not in log\", token_lifetime < 60, \". Token lifetime (exp - iat): \" . token_lifetime . \" s, very short: check the client's access token lifespan in the IdP\", true(), \". Token lifetime (exp - iat): \" . token_lifetime . \" s\"), cause), accounts=mvfilter(match(who, \"^(service account|client certificate)\")), users=case(n_users==1, \"1 user\", n_users>1, n_users . \" users\"), affected=coalesce(mvjoin(mvappend(users, accounts), \", \"), if(isnotnull(mvfind(signatures, \"^ldap_bind_\")), \"service account\", null()), if(isnotnull(mvfind(signatures, \"^kc_admin_realm_update$\")), \"not in log: new starters, at authenticator setup\", null()), \"not in log\") | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | eval _runbook_url=coalesce(runbook_url, \"https://github.com/MarkHawk/identity-lab/tree/main/runbooks\") | table first_seen last_seen cause count affected apps routes runbook _runbook_url"}
    },
    "ds_who": {
      "type": "ds.chain",
      "name": "Users and apps affected",
      "options": {"extend": "ds_failures", "query": "| where isnotnull(who) AND who!=\"not in log\" | fillnull value=\"-\" app | stats min(_time) as first_seen max(_time) as last_seen sum(counted) as count values(cause) as causes by who app | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\")"}
    },
    "ds_proxy_status": {
      "type": "ds.search",
      "name": "Proxy responses by status",
      "options": {"query": "`support_index` sourcetype=idlab:nginx:access status=* | eval response=case(tonumber(status) < 400, substr(status, 1, 1) . \"xx\", match(ssl_client_verify, \"^(NONE|FAILED:)\"), status . \" client certificate\", true(), status) | `support_chart(response)`"}
    },
    "ds_proxy_causes": {
      "type": "ds.search",
      "name": "Proxy refusals by cause",
      "options": {"query": "`support_index` eventtype=idlab_proxy_error | stats count min(_time) as first_seen max(_time) as last_seen values(site) as routes latest(runbook) as runbook latest(runbook_url) as runbook_url by cause | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | eval _runbook_url=runbook_url | table first_seen last_seen cause count routes runbook _runbook_url"}
    },
    "ds_mtls_clients": {
      "type": "ds.search",
      "name": "Client certificates on mutual-TLS routes",
      "options": {"query": "`support_index` sourcetype=idlab:nginx:access ssl_client_verify=* | eval client=coalesce(client_dn, \"no certificate sent\"), not_after=coalesce(replace(client_not_after, \" +\", \" \"), \"-\"), expires=strptime(not_after, \"%b %d %H:%M:%S %Y %Z\"), result=if(ssl_client_verify==\"SUCCESS\", \"accepted\", replace(ssl_client_verify, \"^FAILED:\", \"refused: \")) | eval result=if(result==\"NONE\", \"refused: no certificate\", result) | stats count min(_time) as first_seen max(_time) as last_seen max(expires) as expires values(src) as clients values(site) as routes by client not_after result | eval left=(expires - now()) / 86400, days_left=if(isnull(left), null(), if(left < 0, ceiling(left), floor(left)) + 0), first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | sort - last_seen | table client not_after days_left result count first_seen last_seen clients routes"}
    },
    "ds_egress_status": {
      "type": "ds.search",
      "name": "Egress proxy CONNECTs by result",
      "options": {"query": "`support_index` sourcetype=idlab:squid:access | eval result=case(result_code==\"TCP_TUNNEL\", \"tunnelled\", status==\"407\", \"407\", status==\"403\", \"403\", result_code==\"NONE_NONE\", \"intercepted, no tunnel\", true(), result_code . \"/\" . status) | `support_chart(result)`"}
    },
    "ds_egress_causes": {
      "type": "ds.search",
      "name": "Egress proxy refusals and back-channel failures by cause",
      "options": {"query": "`support_index` (eventtype=idlab_egress_error OR (sourcetype=idlab:sp signature=egress_app_*)) | stats count(eval(like(signature, \"egress_app_%\"))) as app_failures count(eval(like(signature, \"egress_proxy_%\"))) as proxy_refusals min(_time) as first_seen max(_time) as last_seen values(app) as apps values(route) as routes latest(runbook) as runbook latest(runbook_url) as runbook_url by cause | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | eval _runbook_url=coalesce(runbook_url, \"https://github.com/MarkHawk/identity-lab/tree/main/runbooks\") | table first_seen last_seen cause app_failures proxy_refusals apps routes runbook _runbook_url | rename app_failures as \"failed calls (app)\", proxy_refusals as \"refusals (Squid)\""}
    },
    "ds_api_results": {"type": "ds.search", "name": "API calls by result", "options": {"query": "`support_index` eventtype=idlab_api_auth | eval result=coalesce(reason, \"accepted\") | `support_chart(result)`"}},
    "ds_api_reasons": {"type": "ds.search", "name": "API rejections by reason", "options": {"query": "`support_index` eventtype=idlab_api_auth action=failure | stats count min(_time) as first_seen max(_time) as last_seen values(azp) as clients values(aud) as audiences min(token_lifetime) as token_lifetime latest(runbook_url) as runbook_url by reason status | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\"), lifetime=case(reason!=\"expired\", null(), isnull(token_lifetime), \"not in log\", true(), token_lifetime . \" s\"), _runbook_url=runbook_url | table first_seen last_seen reason status count clients audiences lifetime _runbook_url"}},
    "ds_mfa_over_time": {"type": "ds.chain", "name": "MFA failures over time by likely cause", "options": {"extend": "ds_failures", "query": "| search `support_mfa_signatures` | where counted=1 | `support_mfa_what` | `support_chart(mfa_what)`"}},
    "ds_mfa_users": {"type": "ds.chain", "name": "MFA failures by user", "options": {"extend": "ds_failures", "query": "| search `support_mfa_signatures` | where isnotnull(user) | `support_mfa_what` | eval named=if(user_from_id==1, \"from user ID\", \"in log\") | fillnull value=\"-\" app | stats min(_time) as first_seen max(_time) as last_seen sum(counted) as count values(mfa_what) as failures values(app) as apps values(nas_client) as nas values(named) as named by user | sort first_seen | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\") | table user first_seen last_seen count failures apps nas named"}},
    "ds_mfa_nas": {"type": "ds.search", "name": "RADIUS MFA by NAS", "options": {"query": "`support_index` eventtype=idlab_radius_challenge | stats count as challenges dc(user) as mfa_users by nas_client | append [search `support_radius_mfa_events` | `support_radius_mfa` | search sourcetype=idlab:radius action=failure | stats count(eval(signature==\"radius_reject_wrong_code\")) as wrong_codes count(eval(signature==\"radius_reject_unknown_state\")) as unknown_state count(eval(signature==\"radius_challenge_unanswered\" OR like(signature, \"nas_challenge_%\"))) as not_answered count(eval(like(signature, \"nas_challenge_%\"))) as nas_said_why by nas_client] | stats sum(challenges) as challenges max(mfa_users) as mfa_users sum(wrong_codes) as wrong_codes sum(unknown_state) as unknown_state sum(not_answered) as not_answered sum(nas_said_why) as nas_said_why by nas_client | fillnull value=0 challenges mfa_users wrong_codes unknown_state not_answered nas_said_why | rename nas_client as nas, mfa_users as \"MFA users\", wrong_codes as \"wrong codes\", unknown_state as \"unknown State\", not_answered as \"no reply to the challenge\", nas_said_why as \"of which the NAS said why\""}},
    "ds_lockouts": {"type": "ds.search", "name": "Lockouts by rule", "options": {"query": "`support_lockouts` | sort 0 - _time | eval locked_from=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), first_refused=strftime(first_refused, \"%Y-%m-%d %H:%M:%S\"), cleared_at=strftime(cleared_at, \"%Y-%m-%d %H:%M:%S\"), ok_again=strftime(ok_again, \"%Y-%m-%d %H:%M:%S\"), shortest_gap=if(isnull(shortest_gap), \"-\", shortest_gap . \" s\"), _runbook_url=runbook_url | table locked_from user failures shortest_gap rule first_refused refused cleared_at ok_again _runbook_url | rename failures as \"failures before it\", shortest_gap as \"shortest gap\", first_refused as \"first refused\", refused as \"times refused\", cleared_at as \"cleared by an admin\", ok_again as \"next login\""}},
    "ds_radius_unanswered": {"type": "ds.search", "name": "RADIUS challenges with no reply", "options": {"query": "`support_radius_mfa_events` | `support_radius_mfa` | search sourcetype=idlab:radius (signature=radius_challenge_unanswered OR signature=nas_challenge_*) | lookup support_causes signature OUTPUT cause runbook_url | eval nas_said=case(signature==\"nas_challenge_unsupported\", \"challenge-response not enabled\", signature==\"nas_challenge_no_message_authenticator\", \"no Message-Authenticator\", true(), \"nothing logged\"), time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), _runbook_url=runbook_url | sort 0 - _time | table time user nas_client nas_said cause _runbook_url | rename nas_client as nas, nas_said as \"the NAS said\""}},
    "ds_admin_events": {"type": "ds.search", "name": "Keycloak admin changes", "options": {"query": "`support_index` eventtype=idlab_keycloak_admin_event | eval time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), change=lower(operationType) . \" \" . lower(resourceType), note=case(isnotnull(cause), cause, isnotnull(unlocked_user_id), \"An admin cleared a user's lockout (runbook 22)\", true(), null()), _runbook_url=coalesce(runbook_url, if(isnotnull(unlocked_user_id), \"https://github.com/MarkHawk/identity-lab/blob/main/runbooks/22-mfa-lockout.md\", null()), \"https://github.com/MarkHawk/identity-lab/tree/main/runbooks\") | sort 0 - _time | table time change object_path src note _runbook_url | rename object_path as path, src as \"from\""}},
    "ds_radius": {
      "type": "ds.search",
      "name": "RADIUS Access-Reject versus no reply",
      "options": {"query": "`support_index` (sourcetype=idlab:radius OR sourcetype=idlab:nas) radius_outcome=* | eval outcome=radius_outcome . \" (\" . if(sourcetype==\"idlab:nas\", \"NAS\", \"server\") . \")\" | `support_chart(outcome)`"}
    },
    "ds_ldap": {
      "type": "ds.search",
      "name": "LDAP binds refused (result 49)",
      "options": {"query": "`support_index` sourcetype=idlab:slapd (ldap_op=BIND OR ldap_tag=97) | stats min(_time) as time values(bind_dn) as bind_dn values(err) as err by host conn op | where err!=\"0\" | stats min(time) as first_seen max(time) as last_seen count by bind_dn err | eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M:%S\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\"), meaning=case(err==\"49\" AND match(bind_dn, \"^uid=\"), \"invalid credentials: a user's own password\", err==\"49\", \"invalid credentials: service account, check the IdP's bind credential\", true(), \"see RFC 4511\")"}
    },
    "ds_idp_ldap": {
      "type": "ds.search",
      "name": "IdP LDAP errors",
      "options": {"query": "`support_index` eventtype=idlab_keycloak_ldap_error | stats count"}
    }
  },
  "visualizations": {
    "viz_count": {"type": "splunk.singlevalue", "title": "Failures", "dataSources": {"primary": "ds_count"}},
    "viz_users": {"type": "splunk.singlevalue", "title": "Users affected", "dataSources": {"primary": "ds_users"}},
    "viz_first": {"type": "splunk.singlevalue", "title": "First failure", "dataSources": {"primary": "ds_first"}},
    "viz_last": {"type": "splunk.singlevalue", "title": "Latest failure", "dataSources": {"primary": "ds_last"}},
    "viz_over_time": {
      "type": "splunk.column",
      "title": "Failures over time by likely cause",
      "dataSources": {"primary": "ds_over_time"},
      "options": {"stackMode": "stacked", "legendDisplay": "bottom"}
    },
    "viz_by_cause": {
      "type": "splunk.table",
      "title": "When did it start? (select a row for its runbook)",
      "options": {"showInternalFields": false, "count": 60, "columnFormat": {"cause": {"width": 500}}},
      "description": "affected: end users where the logs name them (a wrong one-time code at Keycloak names only the user ID: the name comes from their other events), the service account for directory binds, the client certificate on a mutual-TLS route, otherwise not in log. The realm-change row is an admin event, not a failure: it is not in the counts above",
      "dataSources": {"primary": "ds_by_cause"},
      "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]
    },
    "viz_who": {
      "type": "splunk.table",
      "title": "Who is affected?",
      "description": "End users, service accounts and client certificates named in the logs.",
      "options": {"columnFormat": {"causes": {"width": 560}}},
      "dataSources": {"primary": "ds_who"}
    },
    "viz_proxy_status": {
      "type": "splunk.column",
      "title": "Reverse proxy: responses over time",
      "description": "Every request through the proxy by status. 502, 504: the app behind it failed. 429: its rate limit. 503: it answered by itself (maintenance). 400 client certificate: a mutual-TLS route refused the client's certificate.",
      "dataSources": {"primary": "ds_proxy_status"},
      "options": {
        "stackMode": "stacked",
        "legendDisplay": "bottom",
        "seriesColorsByField": {"2xx": "#9DA5AD", "3xx": "#C3CBD4", "400": "#E3A13B", "400 client certificate": "#B5651D", "429": "#D6731E", "502": "#C2362F", "503": "#8E4BB0", "504": "#7E1E1B"}
      }
    },
    "viz_proxy_causes": {
      "type": "splunk.table",
      "title": "Reverse proxy: refusals by likely cause (select a row for its runbook)",
      "description": "From both of the proxy's logs. Wrong X-Forwarded headers (09) show as a Keycloak error in When did it start? The header-too-large row (10) has no route: nginx cuts that error line short, before its host.",
      "options": {"showInternalFields": false, "columnFormat": {"cause": {"width": 560}}},
      "dataSources": {"primary": "ds_proxy_causes"},
      "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]
    },
    "viz_mtls_clients": {
      "type": "splunk.table",
      "title": "Reverse proxy: client certificates on mutual-TLS routes",
      "description": "Each certificate clients presented, with its expiry (not_after) and what nginx made of it. days_left is from now: a certificate still accepted but close to 0 is the next ticket. no certificate sent: the client presented none (runbook 18).",
      "dataSources": {"primary": "ds_mtls_clients"}
    },
    "viz_egress_status": {
      "type": "splunk.column",
      "title": "Forward proxy (egress): CONNECTs over time",
      "description": "Every call the app behind the egress proxy makes through Squid. Tunnelled is healthy; 407 asks for proxy credentials; 403 is the proxy's policy; intercepted, no tunnel means Squid decrypted the TLS and the client hung up.",
      "dataSources": {"primary": "ds_egress_status"},
      "options": {
        "stackMode": "stacked",
        "legendDisplay": "bottom",
        "seriesColorsByField": {"tunnelled": "#9DA5AD", "407": "#D6731E", "403": "#C2362F", "intercepted, no tunnel": "#7E1E1B"}
      }
    },
    "viz_egress_causes": {
      "type": "splunk.table",
      "title": "Forward proxy (egress): refusals and back-channel failures by likely cause (select a row for its runbook)",
      "description": "Squid's refusals and the app's failed calls to the IdP, each in its own column: one failed login usually shows in both. A bypass (runbook 14) never reaches Squid, so only the app shows it. Squid's TLS row has no route.",
      "options": {"showInternalFields": false, "columnFormat": {"cause": {"width": 500}}},
      "dataSources": {"primary": "ds_egress_causes"},
      "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]
    },
    "viz_api_results": {
      "type": "splunk.column",
      "title": "API (bearer tokens): calls over time by result",
      "description": "Every call with a token: accepted, or refused (401, 400 for a malformed header) by reason. cors_origin_mismatch: the API logged a success, but its CORS header names another origin, so the browser blocked the answer.",
      "dataSources": {"primary": "ds_api_results"},
      "options": {
        "stackMode": "stacked",
        "legendDisplay": "bottom",
        "seriesColorsByField": {"accepted": "#9DA5AD", "wrong_audience": "#C2362F", "expired": "#D6731E", "no_token": "#E3A13B", "not_bearer": "#B5651D", "not_jwt": "#7E1E1B", "cors_origin_mismatch": "#8E4BB0"}
      }
    },
    "viz_api_reasons": {
      "type": "splunk.table",
      "title": "API (bearer tokens): rejections by reason (select a row for its runbook)",
      "description": "clients: the azp the tokens were issued to; audiences: the aud they carry; lifetime: exp - iat. A success in the API's log can still be a CORS failure in the browser (runbook 19).",
      "options": {"showInternalFields": false},
      "dataSources": {"primary": "ds_api_reasons"},
      "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]
    },
    "viz_mfa_over_time": {"type": "splunk.column", "title": "MFA: failures over time by likely cause", "description": "Wrong one-time codes at Keycloak and at the RADIUS server, lockouts, RADIUS challenges the NAS never answered (and why, when the NAS says), and realm settings changes, which can stop new starters setting up an authenticator (runbook 21).", "dataSources": {"primary": "ds_mfa_over_time"}, "options": {"stackMode": "stacked", "legendDisplay": "bottom", "yAxisMajorTickInterval": 1, "seriesColorsByField": {"wrong code (Keycloak)": "#D6731E", "wrong code (RADIUS)": "#E3A13B", "locked out": "#C2362F", "realm settings changed": "#8E4BB0", "challenge not answered": "#7E1E1B", "NAS: no challenge-response": "#B5651D", "NAS: no Message-Authenticator": "#5C3D2E", "unknown State (RADIUS)": "#9DA5AD"}}},
    "viz_mfa_users": {"type": "splunk.table", "title": "MFA: failures by user", "description": "named: in log, or from user ID. Keycloak logs a wrong one-time code with the user's ID only; the name comes from their other events in the time range (the lockout line, or a login at the OIDC app).", "options": {"columnFormat": {"failures": {"width": 240}}}, "dataSources": {"primary": "ds_mfa_users"}},
    "viz_mfa_nas": {"type": "splunk.table", "title": "RADIUS MFA by NAS", "description": "Challenges the server sent each NAS, and what came of them. No reply to the challenge: the NAS never sent the code (runbook 23).", "dataSources": {"primary": "ds_mfa_nas"}},
    "viz_lockouts": {"type": "splunk.table", "title": "MFA: lockouts by rule (select a row for its runbook)", "description": "Keycloak never logs which rule locked an account: it is inferred from the failures since the user's last login (failureFactor 5, quick login under 1 s, as in identity-lab: see support_lockouts). Keycloak logs a lockout only when the locked user tries again.", "options": {"showInternalFields": false, "columnFormat": {"rule": {"width": 420}}}, "dataSources": {"primary": "ds_lockouts"}, "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]},
    "viz_radius_unanswered": {"type": "splunk.table", "title": "RADIUS: challenges with no reply (select a row for its runbook)", "description": "The server asked for a code and the NAS never sent one. Many real NASes log nothing about it: then the NAS said nothing logged, and the server's line is the evidence.", "options": {"showInternalFields": false, "columnFormat": {"cause": {"width": 480}}}, "dataSources": {"primary": "ds_radius_unanswered"}, "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]},
    "viz_admin_events": {"type": "splunk.table", "title": "Keycloak admin changes (select a row for its runbook)", "description": "Keycloak's admin events, newest first. With details off they say what kind of thing changed, never what changed in it. A realm update is a lead for runbook 21, not proof.", "options": {"showInternalFields": false, "columnFormat": {"note": {"width": 480}}}, "dataSources": {"primary": "ds_admin_events"}, "eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "$row._runbook_url.value|n$", "newTab": true}}]},
    "viz_radius": {
      "type": "splunk.column",
      "title": "RADIUS: Access-Reject versus no reply",
      "description": "Access-Reject: the server said no (password, policy). No reply: dropped (shared secret, unknown NAS): a timeout.",
      "dataSources": {"primary": "ds_radius"},
      "options": {"stackMode": "stacked", "legendDisplay": "bottom", "yAxisMajorTickInterval": 1}
    },
    "viz_ldap": {
      "type": "splunk.table",
      "title": "LDAP binds refused by the directory",
      "description": "Result 49 for a service account: the IdP's bind credential is wrong. For a user (uid=...): that user's password.",
      "dataSources": {"primary": "ds_ldap"}
    },
    "viz_idp_ldap": {
      "type": "splunk.singlevalue",
      "title": "IdP LDAP errors",
      "dataSources": {"primary": "ds_idp_ldap"}
    }
  },
